// Prototype only: every world in worlds.json has data, so three EU pairs are marked empty to show the state.
const FAKE_NO_DATA = new Set([11321, 12321, 11322, 12322, 11323, 12323]);
const MATCHED_SINCE = '2026-10-04';

const REGION_COLOR = { NAE: '#2F62E6', NAW: '#0B7A86', EU: '#7B4FD6', LA: '#B9561A', AS: '#C2335F' };
const REGIONS = RAW_WORLDS.map((r) => {
  const worlds = [];
  for (const p of r.pairs) {
    const e = { ...p.elyos, side: 'Elyos', region: r.code, matchedSince: MATCHED_SINCE };
    const a = { ...p.asmodian, side: 'Asmodian', region: r.code, matchedSince: MATCHED_SINCE };
    e.matchedWith = a; a.matchedWith = e;
    for (const w of [e, a]) if (FAKE_NO_DATA.has(w.id)) w.hasData = false;
    worlds.push(e, a);
  }
  return { code: r.code, name: r.name, worlds };
});
const WORLD_BY_ID = new Map(REGIONS.flatMap((r) => r.worlds.map((w) => [w.id, w])));
