const $ = (s, el = document) => el.querySelector(s);
const fmt = (n) => Math.round(n).toLocaleString('en-US');
const fmt2 = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const signed = (n) => (n >= 0 ? '+' : '−') + fmt(Math.abs(n));
const pct = (n) => (n >= 0 ? '+' : '−') + Math.abs(n).toFixed(1) + '%';
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const tierOf = (p) => (p < 0 ? 'F' : p > 60 ? 'S' : p >= 30 ? 'A' : p >= 10 ? 'B' : 'C');
const tierBadge = (p, lg) => `<span class="tier ${tierOf(p)}${lg ? ' lg' : ''}" title="Tier ${tierOf(p)}: ${tierLabel(tierOf(p))}">${tierOf(p)}</span>`;
const tierLabel = (t) => ({ S: 'margin above 60%', A: 'margin 30 to 60%', B: 'margin 10 to 30%', C: 'margin under 10%', F: 'loses Kina' }[t]);
const ico = (name, cls = 'ico') => {
  const it = ICON[name];
  return it ? `<img class="${cls} ${it.grade}" src="${it.icon}" alt="" loading="lazy">` : `<span class="${cls}"></span>`;
};
const icon = (n) => `<i data-lucide="${n}"></i>`;
const chev = icon('chevron-down');
const world = () => WORLD_BY_ID.get(state.worldId);
const region = (code = state.region) => REGIONS.find((r) => r.code === code);
const dateShort = (d) => new Date(d + 'T00:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });
const dateLong = (d) => new Date(d + 'T00:00:00').toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
const marginOf = (low, craft) => low * (1 - state.tax / 100) - craft;

function renderChips() {
  const w = world();
  const r = region();
  const m = state.mastery;
  const planOn = Object.values(state.plan).filter(Boolean).length;
  let html = `
    <button class="chip" data-pop="region" aria-haspopup="dialog"><span class="k kx">Region</span><span class="region-badge" style="background:${REGION_COLOR[r.code]}">${r.code}</span><span class="v kx">${r.name}</span>${chev}</button>
    <button class="chip" data-pop="world" aria-haspopup="dialog" title="${esc(w.name)}, ${r.code}, server ${w.id}"><span class="k kx">World</span><span class="v">${esc(w.name)}</span>${chev}</button>
    <button class="chip" data-pop="world" data-side-chip aria-haspopup="dialog"><span class="k kx">Side</span><span class="side-pill ${w.side}">${w.side}</span>${chev}</button>
    <button class="chip" data-pop="mastery" aria-haspopup="dialog"><span class="k">Mastery</span><span class="mast num">${PROFS.map((p) => `<span><abbr title="${p.key} mastery">${p.ab}</abbr> <b>${m[p.key]}</b></span>`).join('')}</span>${chev}</button>
    <button class="chip" data-pop="tax" aria-haspopup="dialog"><span class="k"><span class="kx">Market tax</span><span class="m-only">Tax</span></span><span class="v num">${state.tax}%</span>${chev}</button>
    <button class="chip" data-pop="plan" aria-haspopup="dialog"><span class="k">Plan</span><span class="v">${planOn} of 3 rules</span>${chev}</button>`;
  if (state.view === 'scanner') {
    html += `<span class="chip-sep" aria-hidden="true"></span><div class="prof-row">
      <button class="chip pc" data-prof="" aria-pressed="${state.prof === null}">All</button>
      ${PROFS.map((p) => `<button class="chip pc" data-prof="${p.key}" aria-pressed="${state.prof === p.key}" title="${p.key}">${icon(p.icon)}<span>${p.key}</span></button>`).join('')}
      <input class="filter-name" type="search" placeholder="Filter by name" aria-label="Filter by name" value="${esc(state.nameFilter)}" id="nameFilter"></div>`;
  }
  $('#chips').innerHTML = html;
  $('#searchRegion').textContent = r.code;
  $('.search-region').style.background = REGION_COLOR[r.code];
}

function renderCalc() {
  const q = state.qty;
  const craft = ITEM.craft * q, buy = ITEM.buy * q;
  const margin = marginOf(ITEM.buy, ITEM.craft) * q;
  const mpct = (marginOf(ITEM.buy, ITEM.craft) / ITEM.craft) * 100;
  const under = buy - craft;
  const w = world();
  const verdictCraft = under > 0;
  return `
  <section class="card item-head" aria-label="Item">
    ${ico(ITEM.name, 'item-icon')}
    <div>
      <h1>${ITEM.name}</h1>
      <div class="item-meta"><span>${ITEM.prof}, recipe level ${ITEM.lvl},</span><span class="grade">${ITEM.grade}</span></div>
    </div>
    <div class="item-ctrl">
      <div class="seg" role="group" aria-label="Result">
        ${['Normal', 'Splendent'].map((r) => `<button data-result="${r}" aria-pressed="${state.result === r}">${r}</button>`).join('')}
      </div>
      <div class="qty"><label for="qty">Qty</label><button data-qty="-1" aria-label="One fewer">−</button><input id="qty" class="num" value="${q}" inputmode="numeric"><button data-qty="1" aria-label="One more">+</button></div>
    </div>
  </section>

  <section class="card verdict" aria-label="Verdict">
    <span class="verdict-tag">${verdictCraft ? 'Craft it' : 'Buy it'}</span>
    <p>${verdictCraft ? `Craft it if you need ${q === 1 ? 'one' : q}.` : 'Buy it.'} Expected cost is <b class="num">${fmt(Math.abs(under))} Kina</b> ${verdictCraft ? 'under' : 'over'} the lowest listing. Selling ${q === 1 ? 'one' : q} earns <b class="num">${fmt(margin)} Kina</b> after ${state.tax}% tax.</p>
  </section>

  <section class="kpis" aria-label="Figures">
    <div class="card kpi"><div class="kpi-label">Craft</div><div class="kpi-fig num">${fmt(craft)}<small>Kina</small></div><div class="kpi-note">4.1 attempts at 96.8% with a 25% combo</div></div>
    <div class="card kpi"><div class="kpi-label">Buy</div><div class="kpi-fig num">${fmt(buy)}<small>Kina</small></div><div class="kpi-note">Lowest of ${ITEM.listings} listings on ${esc(w.name)}</div></div>
    <div class="card kpi margin"><div class="kpi-label">Margin</div><div class="kpi-fig num">${signed(margin)}<small>Kina</small></div><div class="kpi-note num">${pct(mpct)} after ${state.tax}% tax</div><div class="tier-wrap"><span class="lbl">Tier</span>${tierBadge(mpct, true)}</div></div>
  </section>

  <div class="fresh"><span class="dot" aria-hidden="true"></span>Prices from aion2.exchange, captured 21 min ago.<button class="link-btn" type="button">${icon('refresh-cw')}Refresh</button></div>

  <section class="card" aria-label="Details">
    <div class="tabs" role="tablist">
      ${[['buy', 'What to buy', BUY.length], ['make', 'How it is made', LADDER.length], ['rates', 'Rates', null]].map(([k, l, c]) => `<button class="tab" role="tab" data-tab="${k}" aria-selected="${state.tab === k}">${l}${c ? `<span class="count num">${c}</span>` : ''}</button>`).join('')}
    </div>
    <div class="panel" role="tabpanel">${renderTab()}</div>
  </section>`;
}

function renderTab() {
  if (state.tab === 'buy') {
    return `<table class="t stack"><thead><tr><th>Item</th><th>Source</th><th class="r">Expected</th><th class="r">Unit price</th><th class="r">Subtotal</th></tr></thead><tbody>
      ${BUY.map(([n, l, e, u, s]) => `<tr><td><span class="cell-item">${ico(n)}${n}</span></td><td class="src sub-l"><b>Market</b>, ${l} listings</td><td class="r num mhide">${fmt2(e)}</td><td class="r num sub-r"><span class="m-only">${fmt2(e)} × </span>${fmt(u)}</td><td class="r num main">${fmt(s)}</td></tr>`).join('')}
      </tbody><tfoot><tr><td colspan="4">Total</td><td class="r num main">${fmt(ITEM.craft)}</td></tr></tfoot></table>`;
  }
  if (state.tab === 'make') {
    return `<table class="t stack ladder"><thead><tr><th>Step</th><th>How</th><th class="r">Quantity</th><th class="r">Unit cost</th><th class="r">Subtotal</th></tr></thead><tbody>
      ${LADDER.map((s) => `<tr class="lvl${s.lvl}"><td><span class="cell-item">${ico(s.name)}${s.name}</span></td><td class="sub-l"><span class="how ${s.how}">${s.step}</span> <span class="src">${s.note}</span></td><td class="r num sub-r">${s.qty === 1 ? '1' : fmt2(s.qty)}<span class="m-only"> × ${fmt(s.unit)}</span></td><td class="r num mhide">${fmt(s.unit)}</td><td class="r num main">${fmt(s.sub)}</td></tr>`).join('')}
      </tbody></table>`;
  }
  const rows = [
    ['Success chance', 'Mastery 100 against recipe level 30, difference +70', '96.8%'],
    ['Combo chance', null, '25%'],
    ['Combo success', null, '100%'],
    ['Splendent per attempt', null, '0.25'],
    ['Attempts for one Splendent', null, '4.13'],
    ['Success curve', 'metabot.gg, Tailoring level 30', 'Tailoring 30'],
    ['aion2.exchange estimate', 'Cross-check of the craft cost', '9,857,161'],
    ['Difference from our cost', null, '<span class="match-ok">0.000%</span>'],
  ];
  return `<dl class="rates num">${rows.map(([k, s, v]) => `<div><dt>${k}${s ? `<small>${s}</small>` : ''}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
}

function renderScanner() {
  const cols = [
    ['name', 'Item', ''], ['craft', 'Craft cost', 'r'], ['low', 'Market lowest', 'r'], ['margin', 'Margin', 'r'], ['pct', 'Margin %', 'r'],
  ];
  const nf = state.nameFilter.toLowerCase();
  const rows = SCAN.map((r) => ({ ...r, margin: marginOf(r.low, r.craft) }))
    .map((r) => ({ ...r, pct: (r.margin / r.craft) * 100 }))
    .filter((r) => (!state.prof || r.prof === state.prof) && r.name.toLowerCase().includes(nf))
    .sort((a, b) => {
      const k = state.sortKey;
      return (typeof a[k] === 'string' ? a[k].localeCompare(b[k]) : a[k] - b[k]) * state.sortDir;
    });
  const hidden = SCAN_HIDDEN.filter((r) => (!state.prof || r.prof === state.prof) && r.name.toLowerCase().includes(nf));
  const sc = (k) => (state.sortKey === k ? ' sorted' : '');
  const ariaSort = (k) => (state.sortKey === k ? (state.sortDir > 0 ? 'ascending' : 'descending') : 'none');
  const sortIcon = (k) => icon(state.sortKey !== k ? 'chevrons-up-down' : state.sortDir > 0 ? 'arrow-up' : 'arrow-down');
  return `
  <section class="card">
    <div class="scan-head"><h1>Scanner</h1><p>Every recipe you can craft on ${esc(world().name)}, priced with your mastery and ${state.tax}% tax.</p></div>
    <div class="m-sort" role="group" aria-label="Sort by"><span>Sort by</span>${cols.filter(([k]) => k !== 'name').map(([k, l]) => `<button class="chip pc" data-sort="${k}" aria-pressed="${state.sortKey === k}">${l}${state.sortKey === k ? icon(state.sortDir > 0 ? 'arrow-up' : 'arrow-down') : ''}</button>`).join('')}</div>
    <table class="t scan stack">
      <thead><tr>${cols.map(([k, l, c]) => `<th class="${c}" aria-sort="${ariaSort(k)}"><button class="sort-btn" data-sort="${k}">${l}${sortIcon(k)}</button></th>`).join('')}</tr></thead>
      <tbody>
      ${rows.map((r) => `<tr>
        <td class="${sc('name')}"><span class="cell-item">${ico(r.name)}<span>${r.name}<br><span class="prof-tag">${r.prof} ${r.lvl}</span></span></span></td>
        <td class="r num c-craft${sc('craft')}"><span class="m-only">Craft </span>${fmt(r.craft)}</td>
        <td class="r num c-low${sc('low')}"><span class="m-only">Market </span>${fmt(r.low)}</td>
        <td class="r num gain c-margin${sc('margin')}">${signed(r.margin)}</td>
        <td class="r num c-pct${sc('pct')}"><span class="margin-cell"><span class="gain">${pct(r.pct)}</span>${tierBadge(r.pct)}</span></td>
      </tr>`).join('')}
      ${state.showHidden ? hidden.map((r) => `<tr class="hiddenrow">
        <td><span class="cell-item">${ico(r.name)}<span>${r.name}<br><span class="prof-tag">${r.prof} ${r.lvl}</span></span></span></td>
        <td class="r num c-craft"><span class="m-only">Craft </span>${fmt(r.craft)}</td><td class="r c-low"><span class="why">${r.why}</span></td><td class="r c-margin mhide">–</td><td class="r c-pct mhide">–</td></tr>`).join('') : ''}
      ${rows.length === 0 ? `<tr><td colspan="5">No recipe matches. Clear the name filter or pick All professions.</td></tr>` : ''}
      </tbody>
    </table>
    <div class="scan-foot"><span class="num"><b>212 rows hidden</b>: 180 need a price, 32 need more mastery.</span>
      <button class="switch" role="switch" aria-checked="${state.showHidden}" id="showHidden" style="margin-left:auto"><span class="track"></span>Show hidden rows</button></div>
  </section>`;
}

function render() {
  document.querySelectorAll('.view-tab').forEach((a) => a.toggleAttribute('aria-current', false));
  const cur = document.querySelector(`.view-tab[data-view="${state.view}"]`);
  cur.setAttribute('aria-current', 'page');
  renderChips();
  $('#main').innerHTML = state.view === 'calc' ? renderCalc() : renderScanner();
  if (window.lucide) lucide.createIcons();
}

// Popovers
function popHtml(kind) {
  const close = `<button class="pop-close" data-close aria-label="Close">${icon('x')}</button>`;
  const head = (t, sub = '') => `<div class="pop-grab" aria-hidden="true"></div><div class="pop-head"><h2>${t}</h2>${sub ? `<span class="sub">${sub}</span>` : ''}${close}</div>`;
  if (kind === 'region') {
    return head('Region', 'Prices are per world') + `<div class="pop-body"><div class="region-list" role="radiogroup">
      ${REGIONS.map((r) => `<button class="region-opt" role="radio" data-region="${r.code}" aria-checked="${r.code === state.region}"><span class="region-badge" style="background:${REGION_COLOR[r.code]}">${r.code}</span><span class="nm">${r.name}</span><span class="ct num">${r.worlds.length} worlds</span></button>`).join('')}
    </div></div>`;
  }
  if (kind === 'world') {
    const r = region();
    const q = state.worldQuery.trim().toLowerCase();
    let grid;
    if (q) {
      const hits = REGIONS.flatMap((rg) => rg.worlds).filter((w) => w.name.toLowerCase().includes(q));
      grid = hits.length ? hits.map((w) => tile(w, true)).join('') : `<p class="help">No world called "${esc(state.worldQuery)}" in any region.</p>`;
    } else {
      grid = r.worlds.filter((w) => w.side === state.pickSide).map((w) => tile(w, false)).join('');
    }
    return head(`World in ${r.name}`, `${r.worlds.length} worlds`) + `<div class="pop-body">
      <div class="world-tools">
        <div class="seg side" role="group" aria-label="Side">${['Elyos', 'Asmodian'].map((s) => `<button data-pickside="${s}" data-side="${s}" aria-pressed="${state.pickSide === s && !q}">${s} <span class="num" style="font-weight:500;opacity:.7">${r.worlds.filter((w) => w.side === s).length}</span></button>`).join('')}</div>
        <input class="world-search" id="worldSearch" type="search" placeholder="Find a world in any region" aria-label="Find a world in any region" value="${esc(state.worldQuery)}">
      </div>
      <div class="world-grid" role="radiogroup" aria-label="Worlds">${grid}</div>
      <p class="world-note">"vs" is the matched world you meet in the Abyss. NCSoft changes these pairings from time to time. The market stays per world.</p>
    </div>`;
  }
  if (kind === 'mastery') {
    return head('Mastery', 'Per profession, 0 to 100') + `<div class="pop-body">
      ${PROFS.map((p) => `<div class="mast-row">${icon(p.icon)}<label class="nm" for="m-${p.key}">${p.key}${p.game ? `<small>${p.game}</small>` : ''}</label><input type="number" min="0" max="100" class="num" id="m-${p.key}" data-mast="${p.key}" value="${state.mastery[p.key]}"><input type="range" min="0" max="100" data-mast="${p.key}" value="${state.mastery[p.key]}" aria-label="${p.key} mastery"></div>`).join('')}
      <p class="help">Mastery sets the success chance for each recipe. Higher mastery than the recipe level means fewer attempts.</p>
    </div>`;
  }
  if (kind === 'tax') {
    return head('Market tax') + `<div class="pop-body">
      <div class="field"><input id="taxIn" type="number" min="0" max="30" step="0.5" class="num" value="${state.tax}" aria-describedby="taxHelp"><span>% of each sale</span></div>
      <p class="help" id="taxHelp">Find it on the <b>Market screen in game, top right</b>. It lowers what a sale pays out, so it changes the margin and the sell proceeds. Craft and buy costs stay the same.</p>
    </div>`;
  }
  if (kind === 'plan') {
    return head('Plan') + `<div class="pop-body">
      ${PLAN.map((p) => `<label class="plan-opt"><input type="checkbox" data-plan="${p.key}" ${state.plan[p.key] ? 'checked' : ''}><b>${p.name}</b><span>${p.note}</span></label>`).join('')}
    </div>`;
  }
  return '';
}

function tile(w, showRegion) {
  const m = w.matchedWith;
  return `<button class="wtile${w.hasData ? '' : ' nodata'}" role="radio" data-world="${w.id}" aria-checked="${w.id === state.worldId}">
    <span class="wn">${showRegion ? `<span class="region-badge" style="background:${REGION_COLOR[w.region]}">${w.region}</span>` : ''}${esc(w.name)}${showRegion ? `<span class="side-pill ${w.side}">${w.side}</span>` : ''}${w.hasData ? '' : '<span class="nodata-tag">No prices yet</span>'}</span>
    <span class="wm" title="Matched with ${esc(m.name)} (${m.side}) since ${dateLong(w.matchedSince)}">vs ${esc(m.name)}, since ${dateShort(w.matchedSince)}</span>
  </button>`;
}

let anchorKind = null;
function openPop(kind, anchor) {
  const pop = $('#pop');
  state.pop = kind;
  anchorKind = kind;
  pop.className = 'pop ' + kind;
  pop.setAttribute('aria-label', kind);
  pop.innerHTML = popHtml(kind);
  pop.hidden = false;
  $('#scrim').hidden = false;
  document.querySelectorAll('[data-pop]').forEach((b) => b.setAttribute('aria-expanded', 'false'));
  if (anchor) anchor.setAttribute('aria-expanded', 'true');
  if (window.lucide) lucide.createIcons();
  if (anchor && window.innerWidth > 760) {
    const r = anchor.getBoundingClientRect();
    const w = pop.offsetWidth;
    pop.style.top = r.bottom + window.scrollY + 8 + 'px';
    pop.style.left = Math.max(16, Math.min(r.left + window.scrollX, window.innerWidth - w - 16)) + 'px';
  }
}
function refreshPop() {
  if (!state.pop) return;
  const pop = $('#pop');
  const focusId = document.activeElement && document.activeElement.id;
  const caret = document.activeElement && document.activeElement.selectionStart;
  pop.innerHTML = popHtml(state.pop);
  if (window.lucide) lucide.createIcons();
  if (focusId) { const el = document.getElementById(focusId); if (el) { el.focus(); try { el.setSelectionRange(caret, caret); } catch {} } }
}
function closePop() {
  state.pop = null;
  $('#pop').hidden = true;
  $('#scrim').hidden = true;
  const a = document.querySelector('[data-pop][aria-expanded="true"]');
  document.querySelectorAll('[data-pop]').forEach((b) => b.setAttribute('aria-expanded', 'false'));
  if (a) a.focus();
}

function selectWorld(id) {
  const w = WORLD_BY_ID.get(id);
  state.worldId = id; state.region = w.region; state.pickSide = w.side; state.worldQuery = '';
  closePop(); render();
}

document.addEventListener('click', (e) => {
  const t = e.target.closest('button, a, [data-close]');
  if (e.target.id === 'scrim') return closePop();
  if (state.pop && !e.target.closest('#pop') && !e.target.closest('[data-pop]')) closePop();
  if (!t) return;
  if (t.matches('[data-view]')) { e.preventDefault(); state.view = t.dataset.view; history.replaceState(null, '', '#' + state.view); closePop(); return render(); }
  if (t.matches('[data-pop]')) {
    const kind = t.dataset.pop;
    if (state.pop === kind && t.getAttribute('aria-expanded') === 'true') return closePop();
    if (kind === 'world') { state.pickSide = world().side; state.worldQuery = ''; }
    return openPop(kind, t);
  }
  if (t.matches('[data-close]')) return closePop();
  if (t.matches('[data-region]')) {
    const r = region(t.dataset.region);
    const cur = world();
    const same = r.worlds.find((w) => w.name === cur.name) || r.worlds.find((w) => w.side === cur.side && w.hasData);
    state.region = r.code; state.worldId = same.id; state.pickSide = same.side;
    render();
    return openPop('world', document.querySelector('#chips [data-pop="world"]'));
  }
  if (t.matches('[data-pickside]')) { state.pickSide = t.dataset.pickside; state.worldQuery = ''; return refreshPop(); }
  if (t.matches('[data-world]')) return selectWorld(Number(t.dataset.world));
  if (t.matches('[data-result]')) { state.result = t.dataset.result; return render(); }
  if (t.matches('[data-qty]')) { state.qty = Math.max(1, state.qty + Number(t.dataset.qty)); return render(); }
  if (t.matches('[data-tab]')) { state.tab = t.dataset.tab; return render(); }
  if (t.matches('[data-sort]')) {
    const k = t.dataset.sort;
    if (state.sortKey === k) state.sortDir *= -1; else { state.sortKey = k; state.sortDir = k === 'name' ? 1 : -1; }
    return render();
  }
  if (t.matches('[data-prof]')) { state.prof = t.dataset.prof || null; return render(); }
  if (t.id === 'showHidden') { state.showHidden = !state.showHidden; return render(); }
});

document.addEventListener('input', (e) => {
  const t = e.target;
  if (t.id === 'worldSearch') { state.worldQuery = t.value; return refreshPop(); }
  if (t.id === 'nameFilter') {
    state.nameFilter = t.value;
    render();
    const nf = $('#nameFilter'); nf.focus(); nf.setSelectionRange(nf.value.length, nf.value.length);
    return;
  }
  if (t.id === 'qty') { state.qty = Math.max(1, parseInt(t.value, 10) || 1); return; }
  if (t.dataset.mast) {
    const v = Math.max(0, Math.min(100, Number(t.value) || 0));
    state.mastery[t.dataset.mast] = v;
    document.querySelectorAll(`[data-mast="${t.dataset.mast}"]`).forEach((el) => { if (el !== t) el.value = v; });
    renderChips();
    document.querySelector('#chips [data-pop="mastery"]').setAttribute('aria-expanded', 'true');
    if (window.lucide) lucide.createIcons();
    return;
  }
  if (t.id === 'taxIn') {
    state.tax = Math.max(0, Math.min(30, Number(t.value) || 0));
    render();
    document.querySelector('#chips [data-pop="tax"]').setAttribute('aria-expanded', 'true');
    return;
  }
  if (t.dataset.plan) { state.plan[t.dataset.plan] = t.checked; renderChips(); document.querySelector('#chips [data-pop="plan"]').setAttribute('aria-expanded', 'true'); if (window.lucide) lucide.createIcons(); }
});
document.addEventListener('change', (e) => { if (e.target.id === 'qty') render(); });
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && state.pop) closePop(); });
window.addEventListener('resize', () => { if (state.pop && window.innerWidth > 760) openPop(state.pop, document.querySelector(`#chips [data-pop="${state.pop}"]`)); });

// Hash routes for screenshots: #scanner, #world, #region, #mastery, #tax, #plan, #make, #rates, #search=siel, #hidden
function applyHash() {
  const tokens = location.hash.slice(1).split(/[,&+]/).filter(Boolean);
  let pop = null;
  for (const tk of tokens) {
    const [k, v] = tk.split('=');
    if (k === 'scanner' || k === 'calc') state.view = k;
    if (['region', 'world', 'mastery', 'tax', 'plan'].includes(k)) pop = k;
    if (['buy', 'make', 'rates'].includes(k)) state.tab = k;
    if (k === 'asmodian') state.pickSide = 'Asmodian';
    if (k === 'search') { pop = 'world'; state.worldQuery = decodeURIComponent(v || ''); }
    if (k === 'hidden') state.showHidden = true;
    if (k === 'sort') { state.sortKey = v; state.sortDir = -1; }
  }
  render();
  if (pop) openPop(pop, document.querySelector(`#chips [data-pop="${pop}"]`));
}
applyHash();
